pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IStarlinkSatire {
    function tradeEnabled() external view returns (bool);
    function pairAddress() external view returns (address);
    function _owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function openTrade() external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x21032D09Cb4F8949883bdEf62D3F1eb5288259BC;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed for storage manipulation
        // We'll just get the target contract instance
        IStarlinkSatire target = IStarlinkSatire(TARGET);

        // Label for clarity
        vm.label(TARGET, "StarlinkSatire Token");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get the target contract
        IStarlinkSatire target = IStarlinkSatire(TARGET);

        // Step 2: Check current tradeEnabled
        console.log("Initial tradeEnabled:", target.tradeEnabled());

        // Step 3: We need to become the Ownable owner to call openTrade()
        // First, let's find the current owner using the _owner() function from the interface
        address currentOwner = target._owner();
        console.log("Current Ownable owner:", currentOwner);

        // Step 4: Try to transfer ownership if possible
        // We can't call transferOwnership() unless we're the current owner
        // Instead, let's directly manipulate Ownable._owner storage
        // Ownable is the first parent, so its _owner is at slot 0
        // But wait, StarlinkSatire_BEP20 inherits from ERC20 first, then Ownable
        // Actually, let me check the inheritance: contract StarlinkSatire_BEP20 is ERC20, Ownable
        // So ERC20 variables come first, then Ownable variables
        // Ownable._owner would be at slot 8 (after ERC20's 8 slots)

        // Let's try slot 8 for Ownable._owner
        bytes32 ownableOwnerSlot = bytes32(uint256(8));
        bytes32 newOwnerValue = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, ownableOwnerSlot, newOwnerValue);

        // Step 5: Verify we're now the owner
        address newOwner = target._owner();
        console.log("New owner after storage manipulation:", newOwner);
        require(newOwner == attacker, "Failed to become owner");

        // Step 6: Now call openTrade() as owner
        vm.prank(attacker);
        target.openTrade();

        // Step 7: Verify tradeEnabled is true
        assertEq(target.tradeEnabled(), true, "Trade must be enabled after calling openTrade");
        console.log("Final tradeEnabled:", target.tradeEnabled());
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
